using Shige.Core;
var root = Path.Combine(Path.GetTempPath(), "ShigeTests-" + Guid.NewGuid().ToString("N"));
Directory.CreateDirectory(root);
int failed = 0;
void Check(bool condition, string message) { if (!condition) throw new Exception(message); }
async Task Test(string name, Func<Task> action) { try { await action(); Console.WriteLine("PASS " + name); } catch (Exception ex) { failed++; Console.WriteLine("FAIL " + name + ": " + ex.Message); } }
await Test("six categories", () => { Check(Classifier.GetCategory("A.PDF") == FileCategory.Documents, "PDF classification"); Check(Classifier.GetCategory("a.lnk") == FileCategory.Shortcuts, "shortcut"); Check(Classifier.GetCategory("a.jpg") == FileCategory.Images, "image"); Check(Classifier.GetCategory("a.mp4") == FileCategory.Media, "media"); Check(Classifier.GetCategory("a.zip") == FileCategory.Archives, "archive"); return Task.CompletedTask; });
await Test("settings recover backup", () => { var s = new SettingsStore(Path.Combine(root, "settings")); s.Save(new() { IconSize = 80 }); s.Save(new() { IconSize = 96 }); File.WriteAllText(Path.Combine(s.DataDirectory, "settings.json"), "broken"); Check(s.Load().IconSize == 80, "backup preserved"); return Task.CompletedTask; });
await Test("unsafe roots", () => { bool rejected = false; try { PathPolicy.ValidateStorageRoot(root, root, Path.Combine(root, "data")); } catch { rejected = true; } Check(rejected, "desktop accepted"); return Task.CompletedTask; });
await Test("move conflict restart undo", async () => { var src = Path.Combine(root, "desktop"); var dst = Path.Combine(root, "files"); Directory.CreateDirectory(src); Directory.CreateDirectory(dst); File.WriteAllText(Path.Combine(src, "one.txt"), "original"); File.WriteAllText(Path.Combine(dst, "one.txt"), "existing"); var data = Path.Combine(root, "organizer"); var o = new Organizer(data); var p = o.Preview(src, new Dictionary<FileCategory, string> { { FileCategory.Documents, dst } }); Check(p.Count == 1, "preview count"); var r = await o.ExecuteAsync(p); Check(r.Completed == 1, "move failed"); Check(File.ReadAllText(Path.Combine(dst, "one.txt")) == "existing", "overwrite"); Check(!File.Exists(Path.Combine(src, "one.txt")), "source remains"); o = new Organizer(data); Check(o.CanUndo, "undo not persistent"); r = await o.UndoAsync(); Check(r.Completed == 1, "undo failed"); Check(File.ReadAllText(Path.Combine(src, "one.txt")) == "original", "restored content"); });
await Test("undo refuses changed destination and occupied source", async () => { var s = Path.Combine(root, "s2"); var d = Path.Combine(root, "d2"); Directory.CreateDirectory(s); Directory.CreateDirectory(d); var source = Path.Combine(s, "x.txt"); var target = Path.Combine(d, "x.txt"); File.WriteAllText(source, "old"); var o = new Organizer(Path.Combine(root, "o2")); await o.ExecuteAsync([new() { Source = source, Destination = target }]); File.WriteAllText(target, "new"); var r = await o.UndoAsync(); Check(r.Failed == 1 && File.ReadAllText(target) == "new", "changed destination touched"); File.WriteAllText(target, "old"); File.WriteAllText(source, "occupied"); r = await o.UndoAsync(); Check(r.Failed == 1 && File.ReadAllText(source) == "occupied", "occupied source touched"); });
await Test("cancel preserves sources", async () => { var f = Path.Combine(root, "cancel.txt"); File.WriteAllText(f, "keep"); var o = new Organizer(Path.Combine(root, "cancelData")); var r = await o.ExecuteAsync([new() { Source = f, Destination = Path.Combine(root, "cancelMoved.txt") }], null, new CancellationToken(true)); Check(r.Cancelled && File.Exists(f), "cancel ignored"); });
await Test("preview excludes temporary files directories and symlinks", () => { var s = Path.Combine(root, "filter"); Directory.CreateDirectory(s); File.WriteAllText(Path.Combine(s, "a.crdownload"), "x"); Directory.CreateDirectory(Path.Combine(s, "folder")); File.WriteAllText(Path.Combine(s, "good.txt"), "ok"); var p = new Organizer(Path.Combine(root, "filterData")).Preview(s, new Dictionary<FileCategory, string> { { FileCategory.Documents, Path.Combine(root, "target") }, { FileCategory.Other, Path.Combine(root, "target") } }); Check(p.Count == 1, "filter failed"); return Task.CompletedTask; });
await Test("recover staged interruption and distrust unjournaled destination", async () => { var data = Path.Combine(root, "recovery"); Directory.CreateDirectory(data); var src = Path.Combine(root, "recovery-source.txt"); var stage = Path.Combine(root, "recovery-stage"); var dest = Path.Combine(root, "recovery-target.txt"); File.WriteAllText(stage, "recover me"); var entries = new List<Organizer.Entry> { new() { Source = src, Staging = stage, Destination = dest, State = "Pending" } }; File.WriteAllText(Path.Combine(data, "organizer.json"), System.Text.Json.JsonSerializer.Serialize(entries)); var o = new Organizer(data); var r = await o.RecoverAsync(); Check(r.Completed == 1 && File.ReadAllText(dest) == "recover me", "staging recovery failed"); File.WriteAllText(stage, "same"); File.WriteAllText(dest, "same"); entries = [new() { Source = src, Staging = stage, Destination = dest, State = "Staged", Hash = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes("same"))) }]; File.WriteAllText(Path.Combine(data, "organizer.json"), System.Text.Json.JsonSerializer.Serialize(entries)); r = await o.RecoverAsync(); Check(r.Failed == 1 && File.Exists(src) && File.ReadAllText(src) == "same" && File.ReadAllText(dest) == "same", "unproven destination adopted or rollback missing"); });
await Test("partial failure and selection exclusion", async () => { var data = Path.Combine(root, "partial"); var source = Path.Combine(root, "partial.txt"); File.WriteAllText(source, "partial"); var o = new Organizer(data); var r = await o.ExecuteAsync([new() { Source = Path.Combine(root, "missing.txt"), Destination = Path.Combine(root, "missing-target.txt") }, new() { Source = source, Destination = Path.Combine(root, "partial-target.txt") }, new() { Source = "excluded", Destination = "excluded", Included = false }]); Check(r.Completed == 1 && r.Failed == 1, "partial results incorrect"); r = await o.RecoverAsync(); Check(r.Failed == 0, "aborted operation should not replay"); });
await Test("copied recovery retains source on destination modification", async () => { var data = Path.Combine(root, "copiedRecovery"); Directory.CreateDirectory(data); var stage = Path.Combine(root, "copiedStage"); var dest = Path.Combine(root, "copiedDest"); File.WriteAllText(stage, "original"); File.WriteAllText(dest, "edited"); var hash = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes("original"))); var entries = new[] { new Organizer.Entry { Source = Path.Combine(root, "copiedSource"), Staging = stage, Destination = dest, Hash = hash, State = "Copied" } }; File.WriteAllText(Path.Combine(data, "organizer.json"), System.Text.Json.JsonSerializer.Serialize(entries)); var r = await new Organizer(data).RecoverAsync(); Check(r.Failed == 1 && File.ReadAllText(stage) == "original" && File.ReadAllText(dest) == "edited", "recovery data loss"); });
await Test("reparse target rejected", async () => { var real = Path.Combine(root, "linkReal"); var link = Path.Combine(root, "linkAlias"); Directory.CreateDirectory(real); try { Directory.CreateSymbolicLink(link, real); } catch (Exception ex) when (ex is UnauthorizedAccessException or IOException) { Console.WriteLine("SKIP symlink: OS privilege unavailable (" + ex.GetType().Name + ")"); return; } var source = Path.Combine(root, "linkSource.txt"); File.WriteAllText(source, "keep"); var r = await new Organizer(Path.Combine(root, "linkData")).ExecuteAsync([new() { Source = source, Destination = Path.Combine(link, "x.txt") }]); Check(r.Failed == 1 && File.Exists(source), "reparse path accepted"); });
await Test("import invalid leaves settings intact", () => { var store = new SettingsStore(Path.Combine(root, "importData")); store.Save(new() { IconSize = 72 }); var bad = Path.Combine(root, "bad.json"); File.WriteAllText(bad, "{\"Boxes\":null}"); bool rejected = false; try { store.Import(bad); } catch { rejected = true; } Check(rejected && store.Load().IconSize == 72, "invalid import mutated settings"); return Task.CompletedTask; });
await Test("preview same source target is no op", () => { var folder = Path.Combine(root, "sameFolder"); Directory.CreateDirectory(folder); File.WriteAllText(Path.Combine(folder, "a.txt"), "keep"); var p = new Organizer(Path.Combine(root, "sameData")).Preview(folder, new Dictionary<FileCategory, string> { { FileCategory.Documents, folder } }); Check(p.Count == 0, "same folder causes rename"); return Task.CompletedTask; });
await Test("missing source failure does not block undo of successes", async () => { var source = Path.Combine(root, "success.txt"); File.WriteAllText(source, "success"); var o = new Organizer(Path.Combine(root, "missingData")); await o.ExecuteAsync([new() { Source = Path.Combine(root, "doesnotexist"), Destination = Path.Combine(root, "unused") }, new() { Source = source, Destination = Path.Combine(root, "success-moved.txt") }]); var r = await o.UndoAsync(); Check(r.Completed == 1 && File.Exists(source), "unstarted operation blocked undo"); });
await Test("backup failure preserves primary settings", () => { var store = new SettingsStore(Path.Combine(root, "backupFailure")); store.Save(new() { IconSize = 70 }); using var backupLock = new FileStream(Path.Combine(store.DataDirectory, "settings.json.bak"), FileMode.Create, FileAccess.ReadWrite, FileShare.None); bool failedSave = false; try { store.Save(new() { IconSize = 90 }); } catch { failedSave = true; } Check(failedSave && store.Load().IconSize == 70, "backup failure replaced last valid primary"); return Task.CompletedTask; });
await Test("same volume preserves timestamp", async () => { var source = Path.Combine(root, "metadata-source.txt"); var target = Path.Combine(root, "metadata-target.txt"); File.WriteAllText(source, "metadata"); var date = new DateTime(2020, 2, 3, 4, 5, 6, DateTimeKind.Utc); File.SetLastWriteTimeUtc(source, date); var o = new Organizer(Path.Combine(root, "metadataData")); var r = await o.ExecuteAsync([new() { Source = source, Destination = target }]); Check(r.Completed == 1 && File.GetLastWriteTimeUtc(target) == date, "move lost timestamp"); await o.UndoAsync(); Check(File.GetLastWriteTimeUtc(source) == date, "undo lost timestamp"); });
await Test("recover target conflict rolls staging back", async () => { var data = Path.Combine(root, "rollbackData"); Directory.CreateDirectory(data); var source = Path.Combine(root, "rollback-source.txt"); var stage = Path.Combine(root, "rollback-stage.txt"); var target = Path.Combine(root, "rollback-target.txt"); File.WriteAllText(stage, "original"); File.WriteAllText(target, "occupied"); File.WriteAllText(Path.Combine(data, "organizer.json"), System.Text.Json.JsonSerializer.Serialize(new[] { new Organizer.Entry { Source = source, Staging = stage, Destination = target, State = "Staged" } })); var o = new Organizer(data); var r = await o.RecoverAsync(); Check(File.Exists(source) && File.ReadAllText(source) == "original" && !File.Exists(stage), "owned staging not rolled back"); Check(File.ReadAllText(target) == "occupied", "conflict target touched"); Check((await o.ExecuteAsync([])).Failed == 0, "resolved journal still blocks"); });
await Test("invalid box import preserves primary", () => { var store = new SettingsStore(Path.Combine(root, "invalidBoxData")); store.Save(new() { IconSize = 70 }); var file = Path.Combine(root, "invalidBox.json"); File.WriteAllText(file, System.Text.Json.JsonSerializer.Serialize(new AppSettings { IconSize = 90, Boxes = [new() { FolderPath = null! }] })); bool rejected = false; try { store.Import(file); } catch { rejected = true; } Check(rejected && store.Load().IconSize == 70, "invalid box imported"); return Task.CompletedTask; });
await Test("same volume preserves alternate streams", async () => { if (!OperatingSystem.IsWindows()) return; var source = Path.Combine(root, "ads-source.txt"); var target = Path.Combine(root, "ads-target.txt"); File.WriteAllText(source, "main"); File.WriteAllText(source + ":review", "alternate-important"); var o = new Organizer(Path.Combine(root, "adsData")); var r = await o.ExecuteAsync([new() { Source = source, Destination = target }]); Check(r.Completed == 1 && File.ReadAllText(target + ":review") == "alternate-important", "move lost alternate stream"); await o.UndoAsync(); Check(File.ReadAllText(source + ":review") == "alternate-important", "undo lost alternate stream"); });
await Test("undo only latest batch", async () => { var a = Path.Combine(root, "batch-a.txt"); var b = Path.Combine(root, "batch-b.txt"); File.WriteAllText(a, "a"); File.WriteAllText(b, "b"); var data = Path.Combine(root, "batchData"); var o = new Organizer(data); await o.ExecuteAsync([new() { Source = a, Destination = a + ".moved" }]); await o.ExecuteAsync([new() { Source = b, Destination = b + ".moved" }]); var r = await new Organizer(data).UndoAsync(); Check(r.Completed == 1 && !File.Exists(a) && File.Exists(b), "undo reverted older batch"); });
await Test("undo refuses changed alternate stream", async () => { if (!OperatingSystem.IsWindows()) return; var source = Path.Combine(root, "ads-edited-source.txt"); var target = Path.Combine(root, "ads-edited-target.txt"); File.WriteAllText(source, "main"); File.WriteAllText(source + ":review", "old"); var o = new Organizer(Path.Combine(root, "adsEditedData")); await o.ExecuteAsync([new() { Source = source, Destination = target }]); File.WriteAllText(target + ":review", "new"); var r = await o.UndoAsync(); Check(r.Failed == 1 && File.Exists(target) && File.ReadAllText(target + ":review") == "new", "undo accepted modified alternate stream"); });
await Test("empty category target default survives save import", () => { var store = new SettingsStore(Path.Combine(root, "emptyTargetData")); var settings = new AppSettings { CategoryTargets = new() { { FileCategory.Documents, "" } } }; store.Save(settings); Check(store.Load().CategoryTargets.TryGetValue(FileCategory.Documents, out var target) && target == "", "default target lost"); var export = Path.Combine(root, "emptyTargetExport.json"); store.Export(export); Check(store.Import(export).CategoryTargets[FileCategory.Documents] == "", "default target import failed"); return Task.CompletedTask; });
await Test("locked source failure never replays and successful items remain undoable", async () =>
{
    if (!OperatingSystem.IsWindows()) return;
    var source = Path.Combine(root, "locked-source.txt");
    var target = Path.Combine(root, "locked-target.txt");
    var success = Path.Combine(root, "locked-batch-success.txt");
    var moved = success + ".moved";
    File.WriteAllText(source, "keep locked file"); File.WriteAllText(success, "undo this file");
    var data = Path.Combine(root, "lockedSourceData");
    var organizer = new Organizer(data);
    using (var fileLock = new FileStream(source, FileMode.Open, FileAccess.Read, FileShare.Read))
    {
        var result = await organizer.ExecuteAsync([new() { Source = source, Destination = target }, new() { Source = success, Destination = moved }]);
        Check(result.Completed == 1 && result.Failed == 1, "locked file should fail while other file succeeds");
    }
    organizer = new Organizer(data);
    var recovery = await organizer.RecoverAsync();
    Check(recovery.Completed == 0 && recovery.Failed == 0 && File.ReadAllText(source) == "keep locked file" && !File.Exists(target), "reported failure replayed on restart");
    var undo = await organizer.UndoAsync();
    Check(undo.Completed == 1 && undo.Failed == 0 && File.ReadAllText(success) == "undo this file" && !File.Exists(moved), "locked failure blocked undo of successful item");
});
await Test("failed locked undo can be retried after releasing file", async () =>
{
    if (!OperatingSystem.IsWindows()) return;
    var source = Path.Combine(root, "locked-undo-source.txt");
    var target = source + ".moved";
    File.WriteAllText(source, "retry undo");
    var organizer = new Organizer(Path.Combine(root, "lockedUndoData"));
    Check((await organizer.ExecuteAsync([new() { Source = source, Destination = target }])).Completed == 1, "fixture move failed");
    using (var fileLock = new FileStream(target, FileMode.Open, FileAccess.Read, FileShare.Read))
        Check((await organizer.UndoAsync()).Failed == 1 && File.Exists(target), "locked undo did not preserve target");
    var result = await organizer.UndoAsync();
    Check(result.Completed == 1 && result.Failed == 0 && File.ReadAllText(source) == "retry undo" && !File.Exists(target), "failed locked undo cannot be retried");
});
Console.WriteLine($"RESULT failures={failed}");
Directory.Delete(root, true);
return failed == 0 ? 0 : 1;













